3	// INCREASE SIZE OF stockmaster.stockid FROM 20 CHAR TO 64 CHAR
4	//    https://github.com/timschofield/webERP/discussions/812
5	//      - Parts&Vendors allows 50 char
6	//      - @pakricard OpenCart store allows 64 char
7	// 
8	// 1. delete foreign key constraints (Bottom-Up-Drop aka BUD)
9	//
10	// SQL query to list foreign key constraints on stockmaster.stockid:
11	//
12	//     SELECT 
13	//         TABLE_NAME AS 'Referencing Table', 
14	//         COLUMN_NAME AS 'Foreign Key Column', 
15	//         CONSTRAINT_NAME AS 'Constraint Name'
16	//     FROM 
17	//         information_schema.KEY_COLUMN_USAGE
18	//     WHERE 
19	//         REFERENCED_TABLE_NAME = 'stockmaster' 
20	//         AND REFERENCED_COLUMN_NAME = 'stockid'
21	//         AND TABLE_SCHEMA = DATABASE(); -- Limits results to your current webERP database
22	//
23	//   +-----------------------------+--------------------+------------------------------------+
24	//   | Referencing Table           | Foreign Key Column | Constraint Name                    |
25	//   +-----------------------------+--------------------+------------------------------------+
26	//   | bom                         | parent             | bom_ibfk_1                         |
27	//   | bom                         | component          | bom_ibfk_2                         |
28	//   | contractbom                 | stockid            | contractbom_ibfk_3                 |
29	//   | custitem                    | stockid            | custitem_ibfk_1                    |
30	//   | locstock                    | stockid            | locstock_ibfk_2                    |
31	//   | loctransfers                | stockid            | loctransfers_ibfk_3                |
32	//   | mrpdemands                  | stockid            | mrpdemands_ibfk_2                  |
33	//   | offers                      | stockid            | offers_ibfk_2                      |
34	//   | orderdeliverydifferenceslog | stockid            | orderdeliverydifferenceslog_ibfk_1 |
35	//   | pickreqdetails              | stockid            | pickreqdetails_ibfk_1              |
36	//   | prices                      | stockid            | prices_ibfk_1                      |
37	//   | purchdata                   | stockid            | purchdata_ibfk_1                   |
38	//   | recurrsalesorderdetails     | stkcode            | recurrsalesorderdetails_ibfk_2     |
39	//   | salescatprod                | stockid            | salescatprod_ibfk_1                |
40	//   | salesorderdetails           | stkcode            | salesorderdetails_ibfk_2           |
41	//   | stockcheckfreeze            | stockid            | stockcheckfreeze_ibfk_1            |
42	//   | stockcounts                 | stockid            | stockcounts_ibfk_1                 |
43	//   | stockitemproperties         | stockid            | stockitemproperties_ibfk_1         |
44	//   | stockitemproperties         | stockid            | stockitemproperties_ibfk_3         |
45	//   | stockitemproperties         | stockid            | stockitemproperties_ibfk_5         |
46	//   | stockmoves                  | stockid            | stockmoves_ibfk_1                  |
47	//   | stockrequestitems           | stockid            | stockrequestitems_ibfk_2           |
48	//   | stockrequestitems           | stockid            | stockrequestitems_ibfk_4           |
49	//   | stockserialitems            | stockid            | stockserialitems_ibfk_1            |
50	//   | woitems                     | stockid            | woitems_ibfk_1                     |
51	//   | worequirements              | stockid            | worequirements_ibfk_2              |
52	//   +-----------------------------+--------------------+------------------------------------+
53	//   26 rows
54	
55	// 1.1 drop grandchild fk constraints
56	// - indicated by error when attempting to resize grandchild foreign key columns without first deleting constraints
57	// DropConstraint($Table, $Constraint)
58	DropConstraint('stockserialmoves', 'stockserialmoves_ibfk_2'); // compound fk constraint
59	DropConstraint('worequirements', 'worequirements_ibfk_3'); // compound fk constraint
60	
61	// 1.2 drop child fk constraints
62	// DropConstraint($Table, $Constraint)
63	DropConstraint('bom', 'bom_ibfk_1');
64	DropConstraint('bom', 'bom_ibfk_2');
65	DropConstraint('contractbom', 'contractbom_ibfk_3');
66	DropConstraint('custitem', 'custitem_ibfk_1');
67	DropConstraint('locstock', 'locstock_ibfk_2');
68	DropConstraint('loctransfers', 'loctransfers_ibfk_3');
69	DropConstraint('mrpdemands', 'mrpdemands_ibfk_2');
70	DropConstraint('offers', 'offers_ibfk_2');
71	DropConstraint('orderdeliverydifferenceslog', 'orderdeliverydifferenceslog_ibfk_1');
72	DropConstraint('pickreqdetails', 'pickreqdetails_ibfk_1');
73	DropConstraint('prices', 'prices_ibfk_1');
74	DropConstraint('purchdata', 'purchdata_ibfk_1');
75	DropConstraint('recurrsalesorderdetails', 'recurrsalesorderdetails_ibfk_2');
76	DropConstraint('salescatprod', 'salescatprod_ibfk_1');
77	DropConstraint('salesorderdetails', 'salesorderdetails_ibfk_2');
78	DropConstraint('stockcheckfreeze', 'stockcheckfreeze_ibfk_1');
79	DropConstraint('stockcounts', 'stockcounts_ibfk_1');
80	DropConstraint('stockitemproperties', 'stockitemproperties_ibfk_1');
81	DropConstraint('stockitemproperties', 'stockitemproperties_ibfk_3');
82	DropConstraint('stockitemproperties', 'stockitemproperties_ibfk_5');
83	DropConstraint('stockmoves', 'stockmoves_ibfk_1');
84	DropConstraint('stockrequestitems', 'stockrequestitems_ibfk_2');
85	DropConstraint('stockrequestitems', 'stockrequestitems_ibfk_4');
86	DropConstraint('stockserialitems', 'stockserialitems_ibfk_1');
87	DropConstraint('woitems', 'woitems_ibfk_1');
88	DropConstraint('worequirements', 'worequirements_ibfk_2');
89	
90	// 2. change "stockid" parent, child and grandchild foreign key columns (bottom-up order, same as BUD for fk constraints)
91	// 2.1 change grandchild fk columns
92	// ChangeColumnSize($Column, $Table, $Type, $Null, $Default, $Size)
93	ChangeColumnSize('stockid', 'stockserialitems', 'VARCHAR(64)', ' NOT NULL ', '', '64');
94	ChangeColumnSize('stockid', 'worequirements', 'VARCHAR(64)', ' NOT NULL ', '', '64');
95	
96	// 2.2 change child fk columns
97	// ChangeColumnSize($Column, $Table, $Type, $Null, $Default, $Size)
98	ChangeColumnSize('parent', 'bom', 'VARCHAR(64)', ' NOT NULL ', '', '64');
99	ChangeColumnSize('component', 'bom', 'VARCHAR(64)', ' NOT NULL ', '', '64');
100	ChangeColumnSize('stockid', 'contractbom', 'VARCHAR(64)', ' NOT NULL ', '', '64');
101	ChangeColumnSize('stockid', 'custitem', 'VARCHAR(64)', ' NOT NULL ', '', '64');
102	ChangeColumnSize('stockid', 'locstock', 'VARCHAR(64)', ' NOT NULL ', '', '64');
103	ChangeColumnSize('stockid', 'loctransfers',  'VARCHAR(64)', ' NOT NULL ', '', '64');
104	ChangeColumnSize('stockid', 'mrpdemands', 'VARCHAR(64)', ' NOT NULL ', '', '64');
105	ChangeColumnSize('stockid', 'offers', 'VARCHAR(64)', ' NOT NULL ', '', '64');
106	ChangeColumnSize('stockid', 'orderdeliverydifferenceslog', 'VARCHAR(64)', ' NOT NULL ', '', '64');
107	ChangeColumnSize('stockid', 'pickreqdetails', 'VARCHAR(64)', ' NOT NULL ', '', '64');
108	ChangeColumnSize('stockid', 'prices', 'VARCHAR(64)', ' NOT NULL ', '', '64');
109	ChangeColumnSize('stockid', 'purchdata', 'VARCHAR(64)', ' NOT NULL ', '', '64');
110	ChangeColumnSize('stkcode', 'recurrsalesorderdetails', 'VARCHAR(64)', ' NOT NULL ', '', '64');
111	ChangeColumnSize('stockid', 'salescatprod', 'VARCHAR(64)', ' NOT NULL ', '', '64');
112	ChangeColumnSize('stkcode', 'salesorderdetails', 'VARCHAR(64)', ' NOT NULL ', '', '64');
113	ChangeColumnSize('stockid', 'stockcheckfreeze', 'VARCHAR(64)', ' NOT NULL ', '', '64');
114	ChangeColumnSize('stockid', 'stockcounts', 'VARCHAR(64)', ' NOT NULL ', '', '64');
115	ChangeColumnSize('stockid', 'stockitemproperties', 'VARCHAR(64)', ' NOT NULL ', '', '64');
116	ChangeColumnSize('stockid', 'stockmoves', 'VARCHAR(64)', ' NOT NULL ', '', '64');
117	ChangeColumnSize('stockid', 'stockrequestitems', 'VARCHAR(64)', ' NOT NULL ', '', '64');
118	ChangeColumnSize('stockid', 'woitems', 'VARCHAR(64)', ' NOT NULL ', '', '64');
119	
120	// 2.3 change parent key column (stockmaster.stockid)
121	// ChangeColumnSize($Column, $Table, $Type, $Null, $Default, $Size)
122	ChangeColumnSize('stockid', 'stockmaster',  'VARCHAR(64)', ' NOT NULL ', '', '64');
123	
124	
125	// 3. add (re-add) fk constraints (Top-Down-Add aka TDA)
126	// 3.1 add child fk constraints
127	// AddConstraint($Table, $Constraint, $Field, $ReferenceTable, $ReferenceField)
128	AddConstraint('bom', 'bom_ibfk_1', 'parent', 'stockmaster', 'stockid');
129	AddConstraint('bom', 'bom_ibfk_2', 'component', 'stockmaster', 'stockid');
130	AddConstraint('contractbom', 'contractbom_ibfk_3', 'stockid', 'stockmaster', 'stockid');
131	AddConstraint('custitem', 'custitem_ibfk_1', 'stockid', 'stockmaster', 'stockid');
132	AddConstraint('locstock', 'locstock_ibfk_2', 'stockid', 'stockmaster', 'stockid');
133	AddConstraint('loctransfers', 'loctransfers_ibfk_3', 'stockid', 'stockmaster', 'stockid');
134	AddConstraint('mrpdemands', 'mrpdemands_ibfk_2', 'stockid', 'stockmaster', 'stockid');
135	AddConstraint('offers', 'offers_ibfk_2', 'stockid', 'stockmaster', 'stockid');
136	AddConstraint('orderdeliverydifferenceslog', 'orderdeliverydifferenceslog_ibfk_1', 'stockid', 'stockmaster', 'stockid');
137	AddConstraint('pickreqdetails', 'pickreqdetails_ibfk_1', 'stockid', 'stockmaster', 'stockid');
138	AddConstraint('prices', 'prices_ibfk_1', 'stockid', 'stockmaster', 'stockid');
139	AddConstraint('purchdata', 'purchdata_ibfk_1', 'stockid', 'stockmaster', 'stockid');
140	AddConstraint('recurrsalesorderdetails', 'recurrsalesorderdetails_ibfk_2', 'stkcode', 'stockmaster', 'stockid');
141	AddConstraint('salescatprod', 'salescatprod_ibfk_1', 'stockid', 'stockmaster', 'stockid');
142	AddConstraint('salesorderdetails', 'salesorderdetails_ibfk_2', 'stkcode', 'stockmaster', 'stockid');
143	AddConstraint('stockcheckfreeze', 'stockcheckfreeze_ibfk_1', 'stockid', 'stockmaster', 'stockid');
144	AddConstraint('stockcounts', 'stockcounts_ibfk_1', 'stockid', 'stockmaster', 'stockid');
145	AddConstraint('stockitemproperties', 'stockitemproperties_ibfk_1', 'stockid', 'stockmaster', 'stockid');
146	// TODO determine if next 2 stockitemproperties constraints are redundant and if so delete
147	AddConstraint('stockitemproperties', 'stockitemproperties_ibfk_3', 'stockid', 'stockmaster', 'stockid');
148	AddConstraint('stockitemproperties', 'stockitemproperties_ibfk_5', 'stockid', 'stockmaster', 'stockid');
149	
150	// TODO review foreign key constraints in stockitemproperties table for redundant constraints (and delete)
151	
